INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball FX', 'Discover brand new exclusive tables created for Pinball FX, or find your favorites among more than 40 unique and visually enhanced favorites from Zen''s extensive digital pinball library. Relive the most iconic moments from entertainment powerhouses like Indiana Jones, Star Wars, Marvel, Universal Studios, and many more. Enjoy accurate re-creations of the most famous pinball machines of all time with Williams Pinball, or have fun with Zen’s original creations.' FROM games WHERE igdb_id = 185795 ON CONFLICT (game_id, language_code) DO NOTHING;
