INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fear & Hunger 2: Termina', 'Fear & Hunger 2: Termina is oppressive, relentless and hopeless. A mix of jRPG and Survival Horror. Turn-based combat meets resource management. 3 days to explore the wicked town of Prehevil and find out about its dark secrets. 3 days until the pale and sickly green moon rises at its apex. Termina is upon us!' FROM games WHERE igdb_id = 224262 ON CONFLICT (game_id, language_code) DO NOTHING;
