INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Voice of Cards: The Beasts of Burden', 'Voice of Cards: The Beasts of Burden, is a new standalone turn-based RPG adventure, that brings players to an illustrated world presented through the medium of cards as the third release in the Voice of Cards franchise, now giving players the ability to trap the monsters they defeat in cards to use them as skills in battle. This truly unique gaming experience brings back the creative minds behind the previous Voice of Cards games, beloved NieR series and Drakengard series, including: Creative Director, YOKO TARO (Drakengard series, NieR series), Music Director, Keiichi Okabe (Drakengard 3, NieR series) and Character Designer, Kimihiko Fujisaka (Drakengard series).' FROM games WHERE igdb_id = 215058 ON CONFLICT (game_id, language_code) DO NOTHING;
