INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('neko-golf-anime-golf', 223126, '2022-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co68qz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckl6r.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neko Golf: Anime Golf', 'Made by Colopl, the ones who made White Cat Project, an anime golf game for iOS and Android devices. It has an easy to understand swipe swing system that puts you in control with each of your swings. As of right now play as one of five characters and customize them with outfits through the game''s Gatcha system. Earn more clubs and level them up to up your stats to your liking just by playing. No worries about pay to win, even with good stats, your swing really affects the accuracy of your shot, so a lot of this is skill based. You can play casually or competitively in battle mode, make friends, create rooms and play up to 9 holes in public or private matches, voice chat, rank up and enter in weekly tournaments or special events.' FROM games WHERE igdb_id = 223126 ON CONFLICT (game_id, language_code) DO NOTHING;
