INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'After Wave: Downfall', 'After Wave: Downfall is an arcade shooter where the player battles against monsters, completes various missions with a cool battleship. Deathrix invaded the world and released a mysterious meteorite causing a great flood. Players can upgrade their ships for better performance to fight the most brutal enemies. A Local Co-op mode allows the player to team up and adventure with others.' FROM games WHERE igdb_id = 212284 ON CONFLICT (game_id, language_code) DO NOTHING;
