INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Once Upon a Jester', 'Travel the kingdom as Jester with his best friend Sok to improvise theatre shows and perform on stages far and wide. Sing your hearts out, crack jokes and impress audiences to become the stars of the famous Royal Theatrical Spectacle! They embark on a grand adventure across a fantasy kingdom, meeting tons of wacky characters, performing improvised shows and singing their hearts out. Along the way, they unintentionally discover the freedom and joy of musical theatre. Will the pair change their wicked ways or do whatever it takes to get rich?' FROM games WHERE igdb_id = 159553 ON CONFLICT (game_id, language_code) DO NOTHING;
