INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Scarlet', 'The Pokémon Scarlet and Pokémon Violet games, the newest chapters in the Pokémon series, are coming to Nintendo Switch later this year. With these new titles, the Pokémon series takes a new evolutionary step, allowing you to explore freely in a richly expressed open world. Various towns blend seamlessly into the wilderness with no borders. You’ll be able to see the Pokémon of this region in the skies, in the seas, in the forests, on the streets—all over! You’ll be able to experience the true joy of the Pokémon series—battling against wild Pokémon in order to catch them—now in an open-world game that players of any age can enjoy.​' FROM games WHERE igdb_id = 191931 ON CONFLICT (game_id, language_code) DO NOTHING;
