INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kovox Pitch', 'Kovox Pitch is a rhythm-baseball game that has some depth. It comes with a wholesome story and memorable post-punk music. The aim of the game is to swap between two lines in order to successfully hit balls with a baseball bat and experience that 2.5D effect. It has Story mode with story-related events and challenges, and Free Play mode to simply enjoy the game.' FROM games WHERE igdb_id = 133139 ON CONFLICT (game_id, language_code) DO NOTHING;
