INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'River City Girls 2', 'Picking up shortly after the original, River City Girls 2 once again put you in control of Misako and Kyoko - as well as Kunio, Riki, and a few new characters - as they set out on an all-new beat-''em-up adventure across the mean streets of River City. New moves, new enemies, new recruits, new environments, and the return of an old foe await, along with the same over-the-top sense of humor and adrenaline-pumping combat of its predecessor. The game will also feature two-player co-op action both locally and online.' FROM games WHERE igdb_id = 152321 ON CONFLICT (game_id, language_code) DO NOTHING;
