INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Camped Out!', 'Camped Out is a frenetic couch co-op game for friends and families where up to four players must work together to set up camp before darkness falls. Work together as a team to complete campsites and unlock further areas in the game world. Each level is a race against the clock where players are required to build tents, construct a campfire, cook enough food and get into bed before darkness falls.' FROM games WHERE igdb_id = 111257 ON CONFLICT (game_id, language_code) DO NOTHING;
