INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cursed Exped', 'Take part in the first journey of the Cursed Exped. Your mission is to cleanse cursed items in a haunted house. Use your tools to locate and investigate items. Create a ritual area to mark your location of interest and bring items with energy there to progress through the game. Be careful though, the unknown is always watching you and waiting around every corner. Stay safe and happy investigating.' FROM games WHERE igdb_id = 203474 ON CONFLICT (game_id, language_code) DO NOTHING;
