INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Live A Live', 'Previously unreleased outside of Japan, the RPG game Live a Live is releasing on the Nintendo Switch system in the HD-2D style! Seven different stories featuring different protagonists, time periods, and gameplay styles await. In The Wild West, a wanderer with a bounty on his head fights for his life. In the Twilight of Edo Japan, a shinobi undertakes a secret mission. Experience these tales in any order you choose—the adventure is yours to control. What other stories will you uncover on the horizon...?' FROM games WHERE igdb_id = 191407 ON CONFLICT (game_id, language_code) DO NOTHING;
