INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This Way Madness Lies', 'Let us begin our tale, in the quiet city of Verona, Italy. A town for lovers... and giant, mutant flower attacks. As the leader of the Stratford-Upon-Avon High Drama Society, Imogen is no ordinary girl! Sure, she goes to school every day and helps produce plays for the community, but beyond that, she''s a magical girl! With her powers, she can teleport to alternate dimensions based on Shakespeare plays, fight back the forces of Nightmare, and still get back in time for dinner! Join Imogen, Paulina, Viola, Rosalind, Miranda, Beatrice, and Kate on an epic adventure throughout the Shakespearean metaverse in this comedy JRPG!' FROM games WHERE igdb_id = 221775 ON CONFLICT (game_id, language_code) DO NOTHING;
