INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Cities', 'Create your own little city and lean in to watch it come to life. See residents move in and populate your island as it grows from a humble village to a bustling metropolis. Design the layout, strategically plot amenities, and make a perfect city where your citizens love to live. Easy to pick up and play but with lots to discover, Little Cities makes your biggest creations possible!' FROM games WHERE igdb_id = 201654 ON CONFLICT (game_id, language_code) DO NOTHING;
