INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-one-who-pulls-out-the-sword-will-be-crowned-king', 191888, '2022-03-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4iad.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3j50.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The one who pulls out the sword will be crowned king', 'The one who pulls out the sword will be crowned king is a short experimental game about pulling a sword from a stone to be crowned king, like in the Arthurian legend. The game consists entirely of grabbing the sword with your mouse and trying to pull it all the way out. If the cursor stops looking at the sword, your grip will be lost and the sword will fall back to its original position. The Steam version includes an online mode in which the sword gets longer and heavier each time someone pulls it out.' FROM games WHERE igdb_id = 191888 ON CONFLICT (game_id, language_code) DO NOTHING;
