INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cleaver: Sideshow Circus', 'Cleaver: Sideshow Circus is a retro style 8-bit video game. Play as Cleaver: The Killer Clown as he sets out on a quest to collect balloons, meat and save his daughter Lil Miss Cleaver forte clutches of the Circus Du Sinister and its leader the Ring Master. With the help of exploding pumpkins and human hearts the Cleaver should make short work of the bad guys in the classic style Single Screen Platformer.' FROM games WHERE igdb_id = 222111 ON CONFLICT (game_id, language_code) DO NOTHING;
