INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ForeVR Pool', 'ForeVR Pool brings the coolest pool halls from around the globe straight to your living room! Challenge friends, family, and in-game pros to a game of 8-ball pool – no table required. Battle 12 bots to level up and take on Legendary challengers. Join a Quick Match or jump into a private multiplayer party! Friend in town? Share your headset with Pass & Play. Up the ante and stake in-game coins in matches against other players.' FROM games WHERE igdb_id = 225735 ON CONFLICT (game_id, language_code) DO NOTHING;
