INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Quarry', 'It''s late summer in the remote forests of upstate New York, and the teen counselors of Hackett''s Quarry have the camp to themselves for one final night. That means no kids, no adults, and no rules. In this thrilling cinematic tale, you control the fates of all nine camp counselors as their party plans unravel into an unpredictable night of horror. With life-or-death decisions around every turn, the choices you make will determine how the story unfolds.' FROM games WHERE igdb_id = 194404 ON CONFLICT (game_id, language_code) DO NOTHING;
