INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('be-funny-now', 194440, '2022-05-17', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4kui.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1l2c.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Be Funny Now!', 'Be Funny Now is the free-to-play competitive party game that pits your wit against the world! Write and draw your funniest answers to an ever-growing list of hundreds of questions and prompts such as “What really killed the dinosaurs?”, “What’s the Joker’s signature catchphrase?”, and “In just 4 words, ruin a first date!” Once everyone’s answers are in, judge your peers’ work with a shower of roses, a round of applause, or a flurry of tomatoes. Play with friends in private lobbies, or get started immediately in a public lobby for 2-8 player action. Stand out from the crowd with custom outfits, emotes, and more. And be sure to check out the daily prompt - a massive battle royale where everyone has 24 hours to answer the same question/prompt, then votes the best answers to the top where one winner will emerge victorious. Think you’re funny? Prove it…and Be Funny Now!' FROM games WHERE igdb_id = 194440 ON CONFLICT (game_id, language_code) DO NOTHING;
