INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hello-kitty-and-friends-happiness-parade', 204458, '2022-11-18', 66, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7aia.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar29ou.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Kitty and Friends: Happiness Parade', 'Create a grand spectacle with Hello Kitty and friends. Make new allies and lean on your abilities to avoid traps that can rain on your parade! Play as Hello Kitty as you and two friends start a tour through a fantasy world to bring joy to its citizens. Along the way, you''ll find new friends to join you – the more the merrier as the festivities grow. But beware of Kuromi! She''s jealous of your many fans and wants the parade to fail. She''s banded together with Nyanmi, who''s built an army of mechanical underlings to help them with their work. They''ve set traps to ruin all of your hard work. Harness your abilities and the power of friendship to convince everyone – even Kuromi – to join the fun. Dance on, despite the pitfalls, to keep the party going!' FROM games WHERE igdb_id = 204458 ON CONFLICT (game_id, language_code) DO NOTHING;
