INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MopGarden''s Veggie Cart', 'MopGarden’s Veggie Cart is a fast-paced, simulation game where you feed hungry bunnies lots of healthy vegetables! Can you feed them all in time? MopGarden, a variety Twitch streamer, has decided to feed all the local bunnies in her town. As business begins to boom, she moves her veggie cart to other surrounding areas, where the vegetable orders get faster, and faster, and faster.' FROM games WHERE igdb_id = 225879 ON CONFLICT (game_id, language_code) DO NOTHING;
