INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xenoblade-chronicles-3', 191411, '2022-07-29', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ocq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4q12.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xenoblade Chronicles 3', 'A vast world awaits in Xenoblade Chronicles 3, the next game in the acclaimed RPG series from developer Monolithsoft. Players will step into the roles of protagonists Noah and Mio amid turmoil between the hostile nations of Keves and Agnus. Six characters hailing from those nations will take part in a grand tale with “life” as its central theme. Explore a new world that will connect the futures of both Xenoblade Chronicles and Xenoblade Chronicles 2.' FROM games WHERE igdb_id = 191411 ON CONFLICT (game_id, language_code) DO NOTHING;
