INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dexter Stardust: Adventures in Outer Space', 'A spacey classic adventure for all! Dexter Stardust: Adventures in Outer Space is a classic point and click adventure; you can walk, talk, and interact with everything in your surroundings. Use and pick up inventory items to solve puzzles in over 100 unique scenes. Playing Dexter Stardust is like watching back to back episodes of a Saturday morning cartoon! With 5 total episodes, feel free to jump to or replay any episode you’d like, at any time.' FROM games WHERE igdb_id = 153075 ON CONFLICT (game_id, language_code) DO NOTHING;
