INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cult of the Lamb', 'Cult of the Lamb casts players in the role of a possessed lamb saved from annihilation by an ominous stranger, and must repay their debt by building a loyal following in his name. Start your own cult in a land of false prophets, venturing out into diverse and mysterious regions to build a loyal community of woodland worshippers and spread your Word to become the one true cult.' FROM games WHERE igdb_id = 165351 ON CONFLICT (game_id, language_code) DO NOTHING;
