INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cultic', 'You died? So what? Tuck your guts back in and gear up to fight your way through the ranks of a mysterious and twisted cult. You, your guns, and your dynamite will have to shoot, slide, blast, duck, dodge, and maybe throw a gib or two to survive in this old-school-inspired shooter.' FROM games WHERE igdb_id = 164944 ON CONFLICT (game_id, language_code) DO NOTHING;
