INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWE 2K22: NWO 4 - Life Edition', 'WWE 2K returns with all the features you can handle in WWE 2K22, the twenty-sixth professional wrestling game in the WWE game franchise and the ninth game in the WWE 2K series! Get ripped out of the stands and hit with complete control of the WWE Universe. Throw down with the biggest and most realistic-looking WWE Superstars and Legends. Relive pivotal moments in Rey Mysterio''s iconic career in 2K Showcase. Hitting this hard has never been so easy! WWE 2K22: NWO 4 - Life Edition includes: - Undertaker Immortal Pack (3 additional Undertaker characters, MyFACTION EVO cards for Undertaker, MyFACTION Perks and Bonuses) - Season Pass (includes all five DLC content packs, MyCAREER Mega-Boost, SuperCharger packs) - MyFACTION EVO Cards and playable nWO versions of "Hollywood: Hulk Hogan, Scott Hall, Kevin Nash, and Syxx - Eric Bischoff''s playable character, including his MyFACTION EVO Card - Souled Out 1997 and Bash at the Beach 1996 arenas - The nWo Wolfpac Championship - 1 MyFACTION "Gold" Pack bundled with nWo EVO cards' FROM games WHERE igdb_id = 188169 ON CONFLICT (game_id, language_code) DO NOTHING;
