INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gorilla-tag', 143228, '2022-12-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coau8c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4onu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gorilla Tag', 'Reject humanity. Run, climb, and jump in VR using a unique locomotion method that only needs the movement of your hands and arms. No buttons, no sticks, no teleportation. Push off of surfaces to jump and squeeze them with both hands to climb. The game mode is simple tag, for up to 3 players, or infection mode, with 4 or more. Run from the infected gorillas, or outmaneuver the survivors to catch them. Parkour up trees and cliff faces to evade and chase people down. Hang out in a virtual, low-fi jungle with randos or group up in a private room with friends to hang out and play. The stakes are low, so feel free to just chat or make up your own games. The movement is easy to learn, and hard to master. Crossplay with the Quest version of the game, so play with anyone, anywhere. Become gorilla.' FROM games WHERE igdb_id = 143228 ON CONFLICT (game_id, language_code) DO NOTHING;
