INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tile Cities', 'Tile Cities breaks city building down to its very basics making it more of a simple puzzle. Compose nice-looking city maps of randomly generated city blocks (tiles), match colored buildings and parks to meet demand, connect tram lines with depots to get bonuses. Creative mode with no limitations is also available. In this mode you can regenerate random tile until you get the one you like.' FROM games WHERE igdb_id = 198428 ON CONFLICT (game_id, language_code) DO NOTHING;
