INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ceaseless Night', 'Ceaseless Night is a strategic roguelike that captures the essence of dungeon crawling in a bleak world. In a world of stolen sunlight, the flickering flames of a campfire lure unwitting travelers to face the dungeons below. Conquer the dungeons, defeat the Lich King, and end this Ceaseless Night!' FROM games WHERE igdb_id = 221041 ON CONFLICT (game_id, language_code) DO NOTHING;
