INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Homeworld Mobile', 'Embark upon a galactic journey to settle in an unexplored galaxy in this online space strategy game that will require every bit of your wit. Build ships, establish bases, join a clan, engage in coop or solo strategic battles, and discover uncharted systems in this Homeworld-bound space adventure. Battle strategy is key to victory. Command your faction’s fleet and immerse yourself in a dynamic, real time space battle. Take control of spaceship carriers, interceptors, and destroyers to outmaneuver opponents in exciting sci-fi gameplay. Employ strategic battle tactics to gain the upper hand and command your space team to victory.' FROM games WHERE igdb_id = 122124 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 122124 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
