INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Prana', 'An evil king that threatened the world in the past becomes free from his seal after 120 years. The descendants of the heroes who saved the world have to stand up to fight this new evil. However, will the world overcome the suzerainty and racial pride of humans, elves and dwarves to face this threat? A fantastic retro RPG with top quality nostalgic pixel art and a game system worthy of modern times.' FROM games WHERE igdb_id = 200178 ON CONFLICT (game_id, language_code) DO NOTHING;
