INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goat Simulator 3', 'Pilgor’s baaack! Gather your herd and venture forth into Goat Simulator 3; a totally realistic, sandbox farmyard experience. Invite up to three friends in local or online co-op, create carnage together, or compete in mini-games and then not be friends.' FROM games WHERE igdb_id = 204360 ON CONFLICT (game_id, language_code) DO NOTHING;
