INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jinshin', 208100, '2022-06-06', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9wcm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1pul.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jinshin', 'Jinshin is a JRPG based on an ancient-themed fantasy tale of when Kami deities lived alongside humans. Mikazuchi, a man of sword mastery and wisdom, joins the Amaterasu Clan to save his master from Onigami Ichigan, the head of an ominous force. When the war is done, will peace or chaos reign supreme? Make use of tactician Mikazuchi''s orders and gain powerful formation effects to turn the tide of battle in turn-based battles full of ambiance and strategy. Use materials to craft equipment and unlock Kami Arts within weapons to unleash extremely powerful skills. Learn magic arts from Tsukumo Kami hiding all over the world, and focus on developing your village through commands to receive rewards and learn new crafting formulas.' FROM games WHERE igdb_id = 208100 ON CONFLICT (game_id, language_code) DO NOTHING;
