INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-memoir-blue', 106856, '2022-03-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3hep.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4gj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Memoir Blue', 'A Memoir Blue is an atmospheric journey through the memories of Miriam: a champion swimmer, who on the day of her greatest success dwells on her childhood memories of her mother and a special trip they took. Experience this personal story through a beautiful mixture of 3D animation and hand-drawn 2D. Interact and play with dreamlike objects in tactile ways that will surprise and delight players as they dig deeper into what was really happening that day. A gorgeously illustrated story of magical realism, A Memoir Blue shows that the past is a puzzle worth solving.' FROM games WHERE igdb_id = 106856 ON CONFLICT (game_id, language_code) DO NOTHING;
