INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocky & Rocky Reshrined', 'Pocky & Rocky Reshrined follows the adventures of a young Shinto shrine maiden named Pocky and her companion, Rocky the raccoon, as they take on the Nopino Goblins! A third sequel in the series, Pocky & Rocky Reshrined is currently being developed by Tengo Project and expected for release on PlayStation 4 and Nintendo Switch in the second half of 2021. Tengo Project consists of staff who worked on the original, as well as Wild Guns: Reloaded and Ninja Saviors: Return of the Warriors.' FROM games WHERE igdb_id = 144285 ON CONFLICT (game_id, language_code) DO NOTHING;
