INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FarmingCat', 'You''re a cat in a world of islands. You can explore, craft, cook, build, destroy, collect drops and discover items of old ancestors. Don''t worry about monsters, no one will attack you. But you have to care about food, stamina and economy!' FROM games WHERE igdb_id = 204369 ON CONFLICT (game_id, language_code) DO NOTHING;
