INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Snaqe', 'Project Snaqe is an action and precision game inspired by the classic Snake. Your main goal is to collect the minerals scattered through the map, adding cars to your convoy and increasing your high score. The game has 3 different modes with progressive difficulty levels, in addition to the Classic Mode that remounts the traditional Snake gameplay. It also features a variety of obstacles, two navigation modes (drill and shooter), a nostalgic and quite charming pixel art look, great chip-tuney soundtracks and a global ranking system supported by Steam.' FROM games WHERE igdb_id = 189378 ON CONFLICT (game_id, language_code) DO NOTHING;
