INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winter', 'Winter - is an adveture third person game in medieval setting with intense gameplay and exciting combat system which allows you to use different combo moves, tricks and special atacks. Along the way, you will meet creatures that will challenge you to fight and try to get your power. Follow your destiny, let the story tell you about how the first snow fell.' FROM games WHERE igdb_id = 226686 ON CONFLICT (game_id, language_code) DO NOTHING;
