INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aztech Forgotten Gods', 'Aztech Forgotten Gods is the cyber-stone action-adventure following Achtli, a young woman who battles the colossal Forgotten Gods. To uncover the truth behind her far-future Mesoamerican metropolis, she''ll have to turn the Gods'' power against them, as she soars through the city with power and grace using an ancient artifact, remnant of a time long forgotten.' FROM games WHERE igdb_id = 145783 ON CONFLICT (game_id, language_code) DO NOTHING;
