INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Electrician Simulator', 'Take over the family business from your Dad and become an electrician. Learn the basics and test your skills in the Electrician Simulator. Repair and assemble sockets, panels, strips, plugs, chandeliers and even change light bulbs. Oh... and don''t mix up the wires! Results might be shocking.' FROM games WHERE igdb_id = 118473 ON CONFLICT (game_id, language_code) DO NOTHING;
