INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poop Collector', 'The world is overflowing with Poop! You are summoned to help and collect it all! This game has 32 levels, each one has a countdown of only few seconds to clear and collect all of the scat laying around. A simple platformer made with PICO-8 where all you need to do is move left and right and jump from the start point to the exit door after everything is collected.' FROM games WHERE igdb_id = 196169 ON CONFLICT (game_id, language_code) DO NOTHING;
