INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speedcat', 'Speedcat is a tiny 2D platformer where you play as a cat trying to pick up all 32 Speedcoins! Run, jump, and use the environment to navigate your way through the map as quickly as possible. Developed on PICO-8 by Fletch, the game is delightfully small and easy to pick up, with an estimated completion time in under an hour.' FROM games WHERE igdb_id = 198290 ON CONFLICT (game_id, language_code) DO NOTHING;
