INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blossom Tales 2: The Minotaur Prince', 'The Minotaur King has returned...and it''s all your fault! Lily''s back for a new "classic" action-adventure set hundreds of years after The Sleeping King! Grandpa’s latest tale takes you on a journey through haunted forests, pirate shores, and other mysterious lands across a vast open-world! Charming towns, terrible enemies, tricky puzzles, and powerful weapons await you. Enjoy a “story within a story” as Grandpa narrates exciting moments throughout Lily’s incredible adventure. Will you help Lily defeat the Minotaur King and save her brother?' FROM games WHERE igdb_id = 172489 ON CONFLICT (game_id, language_code) DO NOTHING;
