INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gherbert Groundhog in Save the Date', 'Gherbert had just got his burrow laid out perfectly for his upcoming date with his sweetheart. Unfortunately his jealous crazy critter neighbours broke in and stole his belongings. With only hours to go until his big date Gherbert must venture outside to find his stuff and get back to tidy up before his date arrives at 8pm. A traditional retro pixel art platform game. Collect the objects while avoiding the critters before the time runs out!' FROM games WHERE igdb_id = 232406 ON CONFLICT (game_id, language_code) DO NOTHING;
