INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bloons-but-youre-the-bloon', 246094, '2022-11-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobk5g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3hfd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloons But You''re the Bloon', 'Bloons But You''re The Bloon is a fan-made reimagining of the classic tower defence game Bloons in which players use a monkey character to pop balloons (bloons) using various weapons and tools. In this version of the game, the player takes on the role of a bloon and must evade being popped by the monkey characters. As the bloon, the player will navigate through different levels, each with their unique challenges and obstacles. The player must avoid the monkey''s attacks, such as darts, bombs, and boomerangs, and find ways to get past the monkey''s defenses. To do this, the bloon has a range of abilities and upgrades that can be earned throughout the game. The player can customize their bloon by choosing different types of bloons, each with unique abilities and weaknesses. As the player progresses through the game, the monkey characters become more challenging, and the levels become more difficult. The ultimate goal of the game is to make it through all the levels without getting popped by the monkeys.' FROM games WHERE igdb_id = 246094 ON CONFLICT (game_id, language_code) DO NOTHING;
