INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supremacy: The Metaverse Game', 'Supremacy is a collection of games that connect players into one immersive, interactive, and interconnected universe offering a unique experience to those looking for a Metaverse that blurs the line between the real world and the game world. The Battle Arena is a revolutionary sustainable play to earn metaverse game, where AI-controlled NFT War Machines destroy each other in a 24/7 Battle Arena. Influence the battle in your syndicate''s favor using $SUPS to win big rewards.' FROM games WHERE igdb_id = 196789 ON CONFLICT (game_id, language_code) DO NOTHING;
