INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreams of Pain', 'Dreams of Pain is a highly experimental first-person mystery horror game with elements of horror in its atmosphere. The structure of the game is mostly linear. The game incorporates ARG-like elements into its storytelling. The game''s art style was inspired by retro games from the late ''90s. It doesn''t hold your hand and there are no traditional tutorials for the player. Some of the puzzles in the game are types of puzzles not seen in any game before.' FROM games WHERE igdb_id = 201087 ON CONFLICT (game_id, language_code) DO NOTHING;
