INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Norco', 'Norco is a Southern Gothic point & click narrative adventure that immerses the player in the sinking suburbs and verdant industrial swamps of a distorted South Louisiana. Your brother Blake has gone missing in the aftermath of your mother''s death. In the hopes of finding him, you must follow a fugitive security android through the refineries, strip malls, and drainage ditches of suburban New Orleans.' FROM games WHERE igdb_id = 129097 ON CONFLICT (game_id, language_code) DO NOTHING;
