INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nintendo Switch Sports', 'Get moving in Nintendo Switch Sports with Golf, Soccer, Volleyball, Bowling, Tennis, Badminton, and Chambara (swordplay) using Joy-Con controllers! Controls are intuitive, so you can hit the court (or lanes, or field, or arena) and get started. With controlled motions you can curve your bowling ball, add spin to a tennis shot, or even use a Joy-Con with the included Leg Strap accessory to kick the ball in a Soccer Shoot-Out. Family and friends can join in on the fun on the same system or online.' FROM games WHERE igdb_id = 191408 ON CONFLICT (game_id, language_code) DO NOTHING;
