INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dome Keeper', 'Defend against waves of alien monsters in this unique roguelike action mining game. Use the time between attacks to dig beneath the surface in search of valuable resources and relics – deliver them back to your dome to unlock powerful upgrades and useful new gadgets. But it won’t be long until the relentless monsters return - do you risk delving deeper into the mine? Or return to base and prepare for imminent attack? The choice is yours, but make it quickly!' FROM games WHERE igdb_id = 200611 ON CONFLICT (game_id, language_code) DO NOTHING;
