INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CrossfireX', 'CrossfireX delivers an intense first-person shooter experience where players are immersed in a sprawling global conflict between the world’s two most formidable private military factions: Global Risk employs veterans of powerful armed forces who use advanced technologies to fight for order and security; Black List employs hardened mercenaries trained in guerilla tactics who fight to destabilize oppressive regimes in the name of freedom. Choose your side and complete objective-based missions across a variety of classic and innovative modes featuring tightly crafted gameplay and cinematic visuals.' FROM games WHERE igdb_id = 119307 ON CONFLICT (game_id, language_code) DO NOTHING;
