INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Areigna Tactics', 'Areigna Tactics is a top-down hex based strategy game taking place in the world of Areigna, a fantasy world of Humans, Goblins, Dwarfs, and much more. Play in this multiplayer real time strategy game online in ranked matches with people all around the world. Unlike many strategy games which are based on resources held and build times, Areigna’s gameplay and balance focuses instead on cooldowns. These cooldowns vary across different units, and their attack and movement. You will need to balance these cooldowns and constraints in your building of new units, as well in the actions you command your units making their way to the enemy nexus.' FROM games WHERE igdb_id = 197820 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 197820 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
