INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reloader: test_subject', 'Reloader: test_subject is an experimental "Bullet Counting Reload Action" game that features realistic gun control combined with movie-style cinematics. We were inspired by numerous classic shootouts from movies and the indie game called Receiver. Experience being a Reloader: having legendary shooting skills and engaging in Close-Quarters Combat. You just have to remember how to use the gun you''re holding.' FROM games WHERE igdb_id = 168129 ON CONFLICT (game_id, language_code) DO NOTHING;
