INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gale of Windoria', 'Soar on the breezes around the world in your flying Beakle, upgradable with parts to spread your accessible areas. Make use of the elementals not only in turn-based battles, but in dungeon gimmicks as well by combining character abilities. Find also the Quartzes to strengthen your party, acquire skills and techniques. Not to forget the entire world drawn with nostalgic pixel artworks!' FROM games WHERE igdb_id = 208021 ON CONFLICT (game_id, language_code) DO NOTHING;
