INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Race Day Rampage', 'Welcome to Race Day Rampage, a social arcade racing game built for streamers and their audience. In the game, you take on the role of Race Director. You pick the tracks, invite your audience and control the race. Cinematic camera controls let you zoom in on specific racers or areas, or zoom out and watch the race from afar. At the same time, the tracks have various traps that you can control to add to the chaos and influence the race!' FROM games WHERE igdb_id = 208312 ON CONFLICT (game_id, language_code) DO NOTHING;
