INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'What Is Love?: Vol. 1', 'What is Love you may ask... Love is a game. Pretty good one actually, full of pretty girls with dark secrets and everything you ever wanted. Love is in the air and you can breathe deeply. And do other stuff. Deeply. But have in mind that your actions matter so Baby, don''t hurt me!' FROM games WHERE igdb_id = 203921 ON CONFLICT (game_id, language_code) DO NOTHING;
