INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hanna Must Run', 'The game have many levels that you can open by finding cakes. To defeat enemies you need to jump or beat them. At the levels you can find many useful bonuses like shoes that allow you to run fast, a turtle cap that protects against physical attacks, glasses that show the hidden, etc. The more cakes you find, the better the bonuses work.' FROM games WHERE igdb_id = 193390 ON CONFLICT (game_id, language_code) DO NOTHING;
