INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dawn-of-the-monsters', 120562, '2022-03-01', 83, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ijl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5wu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dawn of the Monsters', 'The cataclysmic battle between giant monsters has begun in this manga-inspired, side-scrolling, kaiju beat-''em-up! Titanic creatures known as Nephilim have invaded Earth, and the only hope of stopping them is DAWN (Defense Alliance Worldwide Network), which unleashes its own colossal combatants to defend against the enemy hordes! Take control of four hulking behemoths - Megadon, Aegis Prime, Tempest Galahad, and Ganira - each with distinct abilities and play styles, and smash your way through destructible real-world environments spanning more than 35 missions! Power up with DNA augments, crush foes with devastating Rage moves and brutal finishers, and team up with a friend for 2-player co-op action! You are the planet''s last line of defense...but will that be enough for mankind to survive the Dawn of the Monsters!?' FROM games WHERE igdb_id = 120562 ON CONFLICT (game_id, language_code) DO NOTHING;
