INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby and the Forgotten Land', 'Join Kirby in an unforgettable journey through a mysterious world in a delightful 3D platforming adventure. Take control of the powerful pink puffball, Kirby, and move around freely in 3D stages as you discover a mysterious world with abandoned structures from a past civilization - like a shopping mall?! Copy enemies’ abilities like Sword and Ice and use them to attack and explore your surroundings! What journey awaits Kirby? Take a deep breath and get ready for an unforgettable adventure!' FROM games WHERE igdb_id = 172427 ON CONFLICT (game_id, language_code) DO NOTHING;
