INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumbo Airport Story', 'Make your fledgling airport into a world-famous international landmark jam-packed with entertainment! First build facilities such as Bistros and Bookstores to make visitors comfortable. Satisfied customers make your airport more popular, and will attract even more visitors! But the bigger your airport gets, the more tired visitors will be from walking around... Still, never fear! Simply place seating like Benches and Sofas near facilities, and visitors will be able to rest up.' FROM games WHERE igdb_id = 219930 ON CONFLICT (game_id, language_code) DO NOTHING;
