INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('broken-through--1', 229146, '2022-09-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6h5l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckc4a.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broken Through', '7 years ago, your best friend Leo Williams mysteriously disappeared, and no one had the slightest clue where he went. Seven years after this incident, Leo was declared dead since no one could find him. And now you are in possession of his belongings. But something about his stuff seems off... Something says he''s still out there. And many more too. Broken Through is a full length psychological story rich horror game experience that blends terrifying scenarios with dreamish visuals combined with a nostalgic retro theme. Wander through this world with caution at all time. There’s more than what meets the eye.' FROM games WHERE igdb_id = 229146 ON CONFLICT (game_id, language_code) DO NOTHING;
