INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('scorn', 19817, '2022-10-14', 63, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4v5c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7dp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scorn', 'Scorn is an atmospheric first person horror adventure game set in a nightmarish universe of odd forms and somber tapestry. It is designed around an idea of "being thrown into the world". Isolated and lost inside this dream-like world you will explore different interconnected regions in a non-linear fashion. The unsettling environment is a character itself. Every location contains its own theme (story), puzzles and characters that are integral in creating a cohesive lived in world. Throughout the game you will open up new areas, acquire different skill sets, weapons, various items and try to comprehend the sights presented to you.' FROM games WHERE igdb_id = 19817 ON CONFLICT (game_id, language_code) DO NOTHING;
