INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guns Up! Mobile', 'Guns Up! Mobile is an online PvP strategy game that brings a new twist to Tower Defense battles. Build an army, send your troops into battle and support your soldiers. Give them orders and back them up with your choice of deployments from tanks to airstrikes! A ton of content awaits in this new take on a PlayStation® classic!' FROM games WHERE igdb_id = 175705 ON CONFLICT (game_id, language_code) DO NOTHING;
