INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rwby-arrowfell', 154856, '2022-11-15', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6epe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1yex.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RWBY: Arrowfell', 'Occurring during the events of RWBY Volume 7, players will take control of Team RWBY and switch between them on the fly in solo or multiplayer action (local or online) as they use their trademark weapons and semblances to stop a mysterious new threat in this side-scrolling, 2D adventure. As players explore Atlas, Mantle, and numerous surrounding environments, they will face off against the Creatures of Grimm and other enemies straight from the show, as well as never-before-seen threats. The team also crosses paths with familiar faces including General Ironwood and the Ace Operatives, plus a fearless new group of Huntresses known as Team BRIR.' FROM games WHERE igdb_id = 154856 ON CONFLICT (game_id, language_code) DO NOTHING;
