INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gotham Knights', 'Introducing an original story set in DC’s Batman Universe, Gotham Knights offers a dynamic and interactive Gotham City where an exploding criminal element has swept through the streets. With the Belfry as their base of operations, this new era of heroes will solve mysteries that connect the darkest chapters in the city’s history and must defeat notorious villains in epic confrontations. Players must save Gotham from a descent into chaos and reinvent themselves into their own version of the Dark Knight.' FROM games WHERE igdb_id = 136993 ON CONFLICT (game_id, language_code) DO NOTHING;
