INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Energy Supercross: The Official Videogame 5', 'Hold on fast to the handlebar of your bike because a new chapter of the series has finally arrived. Try Monster Energy Supercross: The Official Videogame 5 and discover the quintessence of indoor supercross! The road to become a true champion starts here. With the new career mode, you''ll have to prove your skills on two-wheel bikes to be able to win glory!' FROM games WHERE igdb_id = 182481 ON CONFLICT (game_id, language_code) DO NOTHING;
