INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Eye', 'In the world of City Eye, you''ll become an operator of the Central Monitoring System, which will try to prevent the effects of every single transgression in the game. Use the city map to track dangerous areas and don''t let the suspects run away from the police. City Eye lets you operate hundreds of cameras at once to have a precise insight into every district you feel that may be endangered. Use this to your advantage and find the danger before it''s too late!' FROM games WHERE igdb_id = 87967 ON CONFLICT (game_id, language_code) DO NOTHING;
