INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('potato-flowers-in-full-bloom', 139252, '2022-03-10', 79, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ht0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7ai.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Potato Flowers in Full Bloom', 'A Japanese indie game being designed as a modern take on the Dungeon RPG genre. It has character creation with a selection for race and class, leveling up provides ability points for further customization. The game uses a party of 3 characters. The dungeon crawling uses grid-based movement and a first-person perspective for exploration but switches to third-person for interactions with NPCs, points of interest or combat encounters. Enemies are visible and don''t appear to roam in the current gameplay. Encounters also doesn''t appear to add extra enemies when combat begins. Combat is turn-based and characters have a stamina meter, it can get dangerous if not managed as even blocking requires a set amount. The enemy''s actions are indicated above them to help the player decide on their actions each turn.' FROM games WHERE igdb_id = 139252 ON CONFLICT (game_id, language_code) DO NOTHING;
