INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crowns and Pawns: Kingdom of Deceit', 'Legends of the past come back to life in this charming European mystery adventure. Crowns and Pawns, a modern-day point and click adventure, inspired by classics such as Broken Sword, Monkey Island, Still Life, Syberia and others. The game highlights the less explored history of Europe to the world of adventurers. Experience the legendary stories of the Grand Duchy of Lithuania, bring to light the villainous branch of the KGB, solve puzzles and follow hints to reveal the secrets of the King who was never crowned.' FROM games WHERE igdb_id = 121704 ON CONFLICT (game_id, language_code) DO NOTHING;
