INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shovel-knight-dig', 122097, '2022-09-23', 83, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9iho.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar64u.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shovel Knight Dig', 'When Drill Knight and his dastardly digging crew blast apart Shovel Knight’s peaceful campsite and steal his loot, he grabs his trusty Shovel Blade and starts tunnelling after them! Meet new friends and foes, visit strange lands, and outfit yourself in your quest to keep the entire land from collapsing underfoot! Jump, slash, and dig your way down an ever-changing chasm of mystery in Shovel Knight Dig, an all-new Shovel Knight adventure!' FROM games WHERE igdb_id = 122097 ON CONFLICT (game_id, language_code) DO NOTHING;
