INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('romancing-saga-minstrel-song-remastered', 203315, '2022-12-01', 67, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7tq9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1vdi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Romancing SaGa: Minstrel Song Remastered', 'Romancing SaGa: Minstrel Song Remastered retains everything that made the original game great. For example, it features the unique “Glimmer” and “Combo” systems, where characters can learn awesome new abilities in the heat of battle, the beautiful illustrations, and the wonderful soundtrack by Composer Kenji Ito. It also features the series’ Free-form Scenario System, which lets you experience the story differently depending on how you play. You choose one of eight main characters, and as you explore the vast world, your actions and decisions will weave a story that is uniquely yours. All that already makes the game a must-play for fans of classic turn-based RPGs, but this release adds even more. The game now features remastered high-definition graphics, new quality-of-life features that make it easier and more convenient to play, and you can even expect some new elements too!' FROM games WHERE igdb_id = 203315 ON CONFLICT (game_id, language_code) DO NOTHING;
