INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Altair Breaker', 'Enter the world of Altair and battle against the army of Laws left behind roaming around Vastus Isle in this Map-based Sword Fighting game. Team up with your friends and experience the feeling of transcendent sword fighting in VR. Climb, glide and collect resources to upgrade your character while playing with your friends.' FROM games WHERE igdb_id = 208682 ON CONFLICT (game_id, language_code) DO NOTHING;
