INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('river-city-girls-zero', 137195, '2022-02-14', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob20q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1gso.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'River City Girls Zero', 'River City Girls Zero lets you experience the first time that Misako and Kyoko teamed up with Kunio and Riki to take to the streets in hard-hitting, curb-stomping action. While the graphics, music, and gameplay all remain true to the classic 16-bit Super Famicom release, this version marks the first time the 1994 game will be localized for the West. A new opening cinematic, new manga cutscenes, and new theme song by River City Girls composer Megan McDuffee have been added as well. Set out solo or team up with a friend in local co-op and discover how the River City Girls story began!' FROM games WHERE igdb_id = 137195 ON CONFLICT (game_id, language_code) DO NOTHING;
