INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elex II', 'Several years after Jax defeated the Hybrid, a new threat arrives from the sky, unleashing the dangerous powers of dark Elex and endangering all life on the planet. In order to defend the peace on Magalan and the safety of his own family, Jax has to go on a mission to convince the factions to unite against the invaders. Dive into a huge, hand-crafted, completely unique world with multiple factions and diverse environments set in a post-apocalyptic science fantasy universe. Explore the vast world of Magalan with your jetpack, and play through the epic story the way you want.' FROM games WHERE igdb_id = 55147 ON CONFLICT (game_id, language_code) DO NOTHING;
