INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oxide: Room 104', 'A bone-chilling body-horror game with escape room gameplay. Bad decisions have brought Matthew to this terrifying motel. Now it’s up to you to decide how to escape – will you make it out alive? Combining escape room gameplay and action, Oxide Room 104 is a bone-chilling single-player body-horror game set inside an old motel. Abducted, at the mercy of a ruthless scientist, and stalked by a horrible creature, you must try to escape using common sense, just as you would in real life. Can you get out of Oxide?' FROM games WHERE igdb_id = 186663 ON CONFLICT (game_id, language_code) DO NOTHING;
