INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fridge is Red', 'The Fridge is Red is an anthology of different first person horror stories. Each episode explores a specific theme and experiments with gameplay ideas. Liminal spaces, surreal encounters and uncanny strangers. You will see a completely mundane settings spiraling down into distorted psychological terror. Experience the dreadful trip inspired by the retro analogue and PS1-era horrors.' FROM games WHERE igdb_id = 141660 ON CONFLICT (game_id, language_code) DO NOTHING;
