INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon Super Rumble', 'Digimon Super Rumble is a free-to-play, massively multiplayer online role-playing game (MMORPG) that brings the world of the popular Digimon franchise to life. Developed by Move Games, this title immerses players in a vibrant, 3D world built with Unreal Engine 4. In Digimon Super Rumble, players take on the role of a Tamer, embarking on an epic adventure to train, evolve, and battle with their Digimon companions. The game features a diverse collection of Digimon from the series, each with its own unique abilities and evolution lines. The core gameplay centers around its turn-based combat system, where players strategically use their Digimon''s skills to overcome challenges. The game combines elements of exploration and collection with a compelling storyline inspired by the Digimon Adventure anime, but with original characters and narratives exclusive to the game. With regular updates and new content, Digimon Super Rumble offers a constantly evolving experience, providing a rich world for both new players and longtime fans to explore and enjoy.' FROM games WHERE igdb_id = 202964 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 202964 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
