INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Weird West', 'Discover a dark fantasy reimagining of the Wild West where lawmen and gunslingers share the frontier with fantastical creatures. Journey through the origin stories of a group of atypical heroes, written into legend by the decisions you make in an unforgiving land. Each journey is unique and tailored to the actions taken - a series of high stakes stories where everything counts and the world reacts to the choices you make. Form a posse or venture forth alone into an otherworldly confines of the Weird West and make each legend your own.' FROM games WHERE igdb_id = 127350 ON CONFLICT (game_id, language_code) DO NOTHING;
