INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moss: Book II', 'Quill is back! And she''s journeying deep into the hexed castle of the Arcane in Moss: Book II, the highly anticipated follow-up to the smash hit VR game Moss. Having rescued her uncle Argus, Quill’s adventure continues with the revelation that a winged tyrant is hunting her within the hexed castle where her uncle was held captive. Moss: Book II is lined with dangerous terrain, challenging puzzles, and enemies twisted in fire and steel.' FROM games WHERE igdb_id = 154839 ON CONFLICT (game_id, language_code) DO NOTHING;
