INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oozescape', 'Oozescape is a challenging 2D platformer where you play as Ooze, a slime creature formed in the depths of a mysterious factory. You guide this newborn life-form through 50 versatile levels while avoiding all the different dangers. The levels have colorful and atmospheric lighting that helps lead Ooze through this strange world. You can further challenge to yourself by trying to achieve the best possible times in all the levels or take your time to get all the collectibles.' FROM games WHERE igdb_id = 191331 ON CONFLICT (game_id, language_code) DO NOTHING;
