INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Strikers: Battle League', 'Introducing Mario Strikers: Battle League, a 5-on-5, soccer-like sport with no rules - do whatever it takes to win! Get gritty and try to score the most goals by tackling enemies, using items, and pulling off score-boosting special shots. Super Mario series mainstays like Peach, Toad, and Yoshi put their cleats (and stats) to the pitch and will stop at nothing to score. Customize your characters with gear that can augment their stats and appearance. Take the carnage online or pass the ball to players locally - just look out for the electric fence.' FROM games WHERE igdb_id = 191398 ON CONFLICT (game_id, language_code) DO NOTHING;
