INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('king-rabbit-race', 185913, '2022-06-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4rq0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4vhs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King Rabbit: Race', 'Hop quickly through deadly obstacle courses and get further than the other rabbits to win! Catchy gameplay and competitive leaderboards will have you playing just one more round. Earn trophies to rank up and face more challenging opponents! Are you skilled enough to place in the top 10 of the daily challenge? A new daily challenge level is generated daily. You''ll be exercising your precision, speed, coordination, and memory. Use the arrow keys or WASD to move and hop your way to victory. Invite & follow your friends to race with them! Includes an in-game marketplace is where you can buy and sell rabbit skins and rings! Rabbit skins are limited to only 100 of each design. With tons of rabbits and new ones being added, you''re sure to find something your style. Decorate your rabbits with rings for unique spawn and death sound effects and particles. Complete quests for soft currency and encounter rare items on encounter islands.' FROM games WHERE igdb_id = 185913 ON CONFLICT (game_id, language_code) DO NOTHING;
