INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('antioch-scarlet-bay', 18451, '2022-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5u6n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1iqc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Antioch: Scarlet Bay', 'Antioch is an online cooperative interactive fiction game. Based on a story written by FibreTigre (the award winning author of Out There), you’ll play as one of two detectives working together to solve a intriguing crime. The adventure will bring you to the city of Antioch, a dark metropolis surrounded by moutains and sea. We love text adventure games, and we wanted to approach them differently. We really believe that multiplayer will breath new life to this genre, giving more depth to your choices, because you’re playing with another human being. Antioch could be summarized as a multiplayer gamebook, playable on all mobile devices (smartphones, tablets and Apple watch).' FROM games WHERE igdb_id = 18451 ON CONFLICT (game_id, language_code) DO NOTHING;
