INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'We Were Here Forever', 'You and your fellow prisoner are trapped in the realm of Castle Rock - were you betrayed, or simply not that clever? To escape, you must explore the sinister castle for puzzles and plot your escape together. Secrets and riddles are hidden in the shadows. Just be aware that nothing is what it seems in this mysterious Antarctic adventure. Can you two escape together, or will you be trapped… forever?' FROM games WHERE igdb_id = 144455 ON CONFLICT (game_id, language_code) DO NOTHING;
