INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gunner, Heat, PC!', 'Gunner, HEAT, PC! is a modern armored warfare game that blends simulation elements with accessible controls. It focuses on contemporary tanks and emphasizes realistic fire control, ballistics, and damage modeling while remaining playable without extensive technical knowledge. The game features single-player content such as campaigns and skirmish missions, as well as cooperative multiplayer. Combat is set within a combined-arms environment, with AI-controlled infantry and support units operating alongside tanks to create varied tactical scenarios.' FROM games WHERE igdb_id = 146417 ON CONFLICT (game_id, language_code) DO NOTHING;
