INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MX vs. ATV: Legends', 'Race your way to victory on bikes, ATVs and UTVs in MX vs ATV Legends! Featuring massive new open environments, plus a career mode that lets you experience all the risks and rewards of becoming a world-famous professional rider. Become an off-road racing legend in your own right! Your time is now!' FROM games WHERE igdb_id = 171216 ON CONFLICT (game_id, language_code) DO NOTHING;
