INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmare Reaper', 'Nightmare Reaper is a dark and violent meld of retro and modern action games, mainly inspired by the classic 2.5D first person shooters of the 90s like Doom, Duke Nukem 3D, Blood, Rise of the Triad and Wolfenstein 3D. Explore the cursed depths of a nightmare while finding powerful weapons and improving your abilities in this retro first person shooter that breaches the wall between the classics and modern sensibilities.' FROM games WHERE igdb_id = 117281 ON CONFLICT (game_id, language_code) DO NOTHING;
