INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Labyrinth of Zangetsu', 'Labyrinth of Zangetsu is new 3D dungeon RPG by Acquire. Its gameplay systems are a return to the "roots" of hack-and-slash. It is a title that emphasizes "wa" (the Japanese-style), which is Acquire’s specialty. It depicts a “deep” world view illustrated by ink painting brush strokes. And features a “mixture of wa” sound that channels the music of Japan’s various eras, from "gagaku" (traditional Japanese music and dance) to "noh" (traditional Japanese masked dance-drama). Labyrinth of Zangetsu is developed based on these four keywords.' FROM games WHERE igdb_id = 203500 ON CONFLICT (game_id, language_code) DO NOTHING;
