INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snow Bros.: Nick & Tom Special', 'One day, the peaceful country of Snow Land is suddenly invaded by King Artich of Kingdom Hotteda Kingdom! The twin princes of Snow Land, Nick, and Tom try to stop him, but in turn, are transformed into snowmen by the curse of King Artich. The twin princesses, Puripuri and Puchipuchi are abducted and Snow Land began melting down and disappearing. Nick and Tom start their long journey to regain peace in Snow Land, rescue the princesses and lift the curse.' FROM games WHERE igdb_id = 198126 ON CONFLICT (game_id, language_code) DO NOTHING;
