INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('in-nightmare', 115862, '2022-03-29', 45, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4lb8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1hz4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'In Nightmare', 'Closing his heart to reality, our protagonist falls into a deep slumber and awakens in a nightmarish dreamworld. In Nightmare is a narrative-driven horror adventure game combining sneak action with diverse puzzles. It follows a young boy in search for the last hope of love who is working out his own salvation by navigating through his fear. Experiencing effects of a broken family, and the heartache it brings, a young child will escape reality into a dark, whimsical world created from his own memories. This sets him on his journey to uncover what truly lies within. Having suffered in reality, his past trauma turns into terrifying monsters that want to keep him in an eternal nightmare. With the help of his dream spirit, the boy will find ways to sneak past enemies, overcome intricate puzzles, embrace his fear, and uncover the truth so that he may be able to purify the monsters he has created, and finally wake up. Will you overcome what you fear or be caught in the nightmare?' FROM games WHERE igdb_id = 115862 ON CONFLICT (game_id, language_code) DO NOTHING;
