INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beyond-contact', 169993, '2022-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3tok.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar149d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beyond Contact', 'Beyond Contact is a fiercely formidable survival game, inspired by the art and style of pulp science-fiction comics, the moral dilemmas of contemporary science-fiction films, and the unforgiving gameplay of survival genre classics. Taking place on the often mysterious and always deadly, procedurally-generated, alien world of Ketern, Beyond Contact features exploration and discovery, a robust system of research and crafting, intuitive base building and defense, farming and creature feeding, narrative-driven objectives to save the inhabitants of the planet, and enough flora, fauna, extreme weather, and environmental hazards to kill even the toughest players 1000 times over... and trust us if the planet gets the chance, it will.' FROM games WHERE igdb_id = 169993 ON CONFLICT (game_id, language_code) DO NOTHING;
