INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'How to Say Goodbye', 'How to say Goodbye tells the story of a character recently turned into a ghost, lost in an unknown world populated by spirits. In this narrative puzzle game, move the elements of decor and the characters to guide them out of the liminal space between life and death in which they are trapped. Help them find their friends who are prisoners of a mysterious wizard and accompany them on their journey to the other side.' FROM games WHERE igdb_id = 126445 ON CONFLICT (game_id, language_code) DO NOTHING;
