INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aircraft Carrier Survival', 'When the harshness of the sea meets the cruelties of war, a challenge for perseverance makes itself known. Welcome to Aircraft Carrier Survival, a strategy game set in the Pacific Theater of World War II, where your prowess as a commander decides the fate of a naval behemoth. Take control of the aircraft carrier, its crew, officers, and planes during WW2. Exercise your military prowess by choosing the right equipment, crew, and escort for the mission. Remember that your success will depend greatly on your flexibility in managing the available fleet resources.' FROM games WHERE igdb_id = 139380 ON CONFLICT (game_id, language_code) DO NOTHING;
