INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Life Makeover', 'Life Makeover is a social simulation game, you can create your very own avatar, customize dress-up and makeup, and you could even be a designer, from cutting to sewing, DIY a unique set of your outfit. Dream home, from locating to interior design, build the very home for you by yourself, invite your BFFs to have a party anytime, and chat freely in your space! Bring Your Dreams to Life - Inspire Life Makeover now with your shining free will!' FROM games WHERE igdb_id = 212426 ON CONFLICT (game_id, language_code) DO NOTHING;
