INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nope Nope Nurses', 'Hospital ≠ hospitality...?! Yamada is afflicted with a rare condition that makes his life hard, and when he manages to break bones in both his hands too, he ends up on a medical bed with beautiful nurses tending to his every need. Make no mistake, though—these nurses are vicious and no love sparks fly… Will young Yamada leave the hospital with his sanity intact?' FROM games WHERE igdb_id = 215754 ON CONFLICT (game_id, language_code) DO NOTHING;
