INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('domino-earning-world', 321265, '2022-10-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co99sg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scucs8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Domino Earning World', 'It is the first platform for this game, based on blockchain that unites millions of domino enthusiasts in a community where they will be able to buy and create their own NFTs such as avatars and accessories. In addition, they will be able to organize games including tournaments in gaming centers. DEW will combine multi-million dollar video game-based marketplaces and a popularized millennial game, all merged by blockchain and NFT technologies. There are not many video games that offer players the opportunity to generate real profits. We believe there is a huge opportunity in the video game market with “play to win” features. This is skill-based gaming with the potential for real-world monetary rewards. The slow digitization and lack of transparency of the NFT gaming market, gave us the ability to see the great niche for the creation of Dominoes as NFT. Online domino game platforms with modern graphics, extensive gameplay possibilities and, most importantly, blockchain is what the market wants.' FROM games WHERE igdb_id = 321265 ON CONFLICT (game_id, language_code) DO NOTHING;
