INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sympathy Kiss', 'Sympathy Kiss is an otome game by Otomate that involves the heroine who was working for almost a year at an app development company and was used to the usual mediocrity of work. However, she is suddenly reassigned to the production department of an app that is about to end its service. She has to choose the ideal partner that will keep the app alive for years to come. Just what awaits her–?!' FROM games WHERE igdb_id = 222359 ON CONFLICT (game_id, language_code) DO NOTHING;
