INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Netrunner Awaken1ng', 'A fast paced 3D plateform-parkour game in procedurally generated levels in which the player hacks the Matrix by collecting all the Datas in time and going as far as possible before being caught by the Logout(). By running and jumping from walls to walls as fast as possible, you will discover, learn and by-pass each new database defenses you will encounter throughout the levels. Or die, repeat, improve and succeed! Unlock each level by hacking its password using clues from previous levels!' FROM games WHERE igdb_id = 182393 ON CONFLICT (game_id, language_code) DO NOTHING;
