INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dark-light', 126237, '2022-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co26gf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arqk9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Light', 'Dark Light is a Sci-fi 2D action-platformer, metroidvania, souls-like inspired game. Explore apocalypse cyberpunk world full of supernatural beings. Encounter and defeat creatures of darkness which are invisible to the naked eye, detected only with the light source of your drone. Experience the horror and feel their presence as they surround you. As a Dark-Hunter you were dropped into a wrecked world. To survive, you need to equip yourself, fight through your way, collecting ‘shards’ from killing super nature creatures to reinforce your energy. Through surviving, you will explore the mysterious dark zones of the apocalypse world. FEATURES - Cinematic quality graphic, detailed characters and environment design, vivid animation with lush visual effect. - Variety of range, melee, throwable weapons, and unique items, multiple ways to upgrade weapons, special equipment and player to shape your own character skills. - Non-linear map structure for you to choose your own path to explore the dark zones, encounter horrifying supernatural enemies, fearsome bosses, and friendly NPC, fight with invisible creatures that only can be seen in the special light source. -Detect invisible enemies and reveal hidden path with a special light source from your drone.' FROM games WHERE igdb_id = 126237 ON CONFLICT (game_id, language_code) DO NOTHING;
