INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monument Valley 2: Panoramic Edition', 'Perception meets reality in Monument Valley 2, the atmospheric return of the acclaimed smash hit Monument Valley. Explore, Grow and Guide Ro and her Child through a magical and moving world. Discover illusionary pathways and delightful puzzles as you learn the secrets of The Sacred Geometry. In this meditative and calming puzzle game, follow the heart warming story of Ro in her journey through motherhood. Rediscover independence through manipulating monuments and evolving paths to explore new, surreal, and mysterious worlds.' FROM games WHERE igdb_id = 203388 ON CONFLICT (game_id, language_code) DO NOTHING;
