INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Knight Witch', 'The Knight Witch is a metroidvania adventure game with fast-paced, shoot ''em up combat set in a beautifully hand-drawn world. Cast devastating card-based spells, forge close bonds, and make moral choices all in your quest to save your home and discover who''s behind the War Golem invasion.' FROM games WHERE igdb_id = 201483 ON CONFLICT (game_id, language_code) DO NOTHING;
