INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broken Edge', 'Broken Edge is a VR multiplayer fantasy dueling game where you embody historical sword fighters. Use their unique techniques and powers combined with cutting-edge fencing mechanics to claim victory against online components and climb the ranks! All characters are equipped with unique weapons, coupled with their own distinctive martial arts style. Learn to master these ancient fighting patterns to awaken the energy of your blade and dominate your foes online.' FROM games WHERE igdb_id = 204335 ON CONFLICT (game_id, language_code) DO NOTHING;
