INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA 2K23', 'Rise to the occasion in NBA 2K23. Showcase your talent in MyCareer. Pair All-Stars with timeless legends in MyTeam. Build your own dynasty in MyGM, or guide the NBA in a new direction with MyLeague. Take on NBA or WNBA teams in "Play Now" and feel true-to-life gameplay.' FROM games WHERE igdb_id = 207393 ON CONFLICT (game_id, language_code) DO NOTHING;
