INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'As Dusk Falls', 'As Dusk Falls is an original interactive drama from INTERIOR/NIGHT that explores the entangled lives of two families across thirty years. Starting in 1998 with a robbery-gone-wrong in small town Arizona, the choices you make have a powerful impact on the characters’ lives in this uncompromising story of betrayal, sacrifice and resilience. Drive the lives and relationships of multiple characters in a decades-spanning story told across two intense books.' FROM games WHERE igdb_id = 135995 ON CONFLICT (game_id, language_code) DO NOTHING;
