INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Construction Simulator', 'Construction Simulator is back - bigger and better than ever! Get back to work and help yourself to a huge fleet of vehicles that will blow your mind. In addition to the brands already familiar from other games in the Construction Simulator series, such as Caterpillar, CASE and BELL, you can now take the wheel of new licensed construction machines from partners such as DAF and Doosan and choose from a total of over 70 construction machines!' FROM games WHERE igdb_id = 206188 ON CONFLICT (game_id, language_code) DO NOTHING;
