INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Opus: Echo of Starsong - Full Bloom Edition', 'Opus: Echo of Starsong - Full Bloom Edition is the definitive edition of the visual novel style adventure game, now with all new voice acting. Asteroids emitting a sound known as "Starsongs" have become the center of conflict for the immense power they hold. Determined to claim asteroids of his own, a young man ventures out with a girl who can imitate starsongs, lending her voice to unravel an ancient myth deep in the heart of space.' FROM games WHERE igdb_id = 200915 ON CONFLICT (game_id, language_code) DO NOTHING;
