INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doraemon Story of Seasons: Friends of the Great Kingdom', 'Doraemon, Noby and their friends land on an unknown planet and decide to help a new friend fulfill his dreams—by farming! Plow the fields, harvest crops and tend to the animals. You can even use Doraemon’s secret gadgets to farm in a flash! Relax by living with friends, eating delicious meals and fishing. And with local play, you and a pal can build a ranch together!' FROM games WHERE igdb_id = 206815 ON CONFLICT (game_id, language_code) DO NOTHING;
