INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soccer Story', 'It''s been a year since The Calamity tore apart the very foundations of soccer as we know it, and since then, Soccer Inc. has made dang well sure that not a soul has been allowed to even look at a soccer ball, let alone kick it. Soccer may have been banned across the world... but now there is hope! A magical soccer ball has chosen you, our Savior of Soccer! Soccer Story is a physics-driven adventure RPG, where every problem can be solved with your trusty magic ball.' FROM games WHERE igdb_id = 213264 ON CONFLICT (game_id, language_code) DO NOTHING;
