INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Alone Ep.2: Daddy', 'George''s mind journey continues in Lost Alone EP. 2 - Daddy. George wakes up in a house that is familiar to him. He doesn''t know what year it is. He doesn''t know how he got into that house. Time and space lose all meaning. As his memory begins to come together, he realizes that he has ended up in his worst nightmare: his childhood!' FROM games WHERE igdb_id = 185912 ON CONFLICT (game_id, language_code) DO NOTHING;
