INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('masks-of-deception--1', 200705, '2022-06-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4qo0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1mxi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Masks of Deception', 'Masks of Deception is a 6 player multiplayer game where you must work together to find and expel a demon. However, correctly identifying the monster will be difficult as one of you has been possessed and turned against the rest. Use your senses and investigative tools to gather the information required to send this hellish creature back to the depths from whence it came, all while avoiding the fatal wretched beings that stalk these haunted lands. Note that one chance is all you get, and any mistake can lead to utter failure.' FROM games WHERE igdb_id = 200705 ON CONFLICT (game_id, language_code) DO NOTHING;
