INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tower Princess', 'TowerPrincess is a 3D action-platformer that recovers the spirit of the classical adventure games, as Zelda, Crash Bandicoot, Ratchet & Clank or Mario, and merges it with roguelike mechanics! This means that the dungeon, the rewards, the challenges or even the character will be procedural, making every gameplay unique! It''s a parody of the classical "knight who enters into the dragon''s castle and rescues the princess". Only that this time one does not just "rescue the princess". The knight will have to date her while goes through the dungeon, before the evil Dragon notices him and burns everything down!' FROM games WHERE igdb_id = 115661 ON CONFLICT (game_id, language_code) DO NOTHING;
