INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forlorn', 'Anyone can survive for a day. But can you survive the nights? Forlorn is a single-player survival horror game. Lost on a deserted island, you will have to forage, craft, build, hunt and explore your way through the wilderness. The clock is ticking, as every night could be your last.' FROM games WHERE igdb_id = 198858 ON CONFLICT (game_id, language_code) DO NOTHING;
