INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stray', 'Stray is a third-person cat adventure game set amidst the detailed neon-lit alleys of a decaying cybercity and the murky environments of its seedy underbelly. Roam surroundings high and low, defend against unforeseen threats and solve the mysteries of this unwelcoming place inhabited by nothing but unassuming droids and dangerous creatures. See the world through the eyes of a stray and interact with the environment in playful ways. Be stealthy, nimble, silly, and sometimes as annoying as possible with the strange inhabitants of this foreign world.' FROM games WHERE igdb_id = 110248 ON CONFLICT (game_id, language_code) DO NOTHING;
