INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'OneShot: World Machine Edition', 'The World Knows You Exist. Experience an adventure game with puzzles that go beyond its own window and establish a unique bond with the main character. In OneShot: World Machine Edition, you discover a strange computer operating system with a self-contained world installed. Explore this world to unravel its mysteries and help guide a child on their mission to restore the long-dead sun. You hear that saving the world may no longer be possible… But it’s worth a shot, you think. Now with collectible content and features exclusive to the World Machine Edition!' FROM games WHERE igdb_id = 200905 ON CONFLICT (game_id, language_code) DO NOTHING;
