INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ballads at Midnight', 'When a sarcastic bard is arrested and exiled to an abandoned castle, she expected to be at the mercy of a hungry, blood-thirsty vampire. She soon discovers that the vampire, Lucius, is not starving: he is gravely bored. She may just survive on borrowed time, one ballad each midnight.' FROM games WHERE igdb_id = 207399 ON CONFLICT (game_id, language_code) DO NOTHING;
