INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crashword', 'Crashword is a co-operative party word game that''s fun for all ages! Each turn, one single player is the guesser trying to guess a secret word; everyone else is a clue-giver. Each clue-giver submits a one word clue, trying to help the guesser guess the secret word. All duplicate clues (crashes) are thrown out, and the guesser only sees the clues that were unique.' FROM games WHERE igdb_id = 206924 ON CONFLICT (game_id, language_code) DO NOTHING;
