INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TeamJumpers 2: New Reality', 'The ambitious sequel from Imperfect Studios! TeamJumpers 2: New Reality, is an ambitious sequel to TeamJumpers. And the focus on this one''s theme is interdimensional travel. Every 10 levels, you will discover a new reality. With challenging bosses, a simple yet fun combat system, and secrets to be revealed, this world is yours to explore!' FROM games WHERE igdb_id = 152032 ON CONFLICT (game_id, language_code) DO NOTHING;
