INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kryxivia', 'Kryxivia is a fantasy 3D MMORPG game directly available on our website at kryxivia.io, a whole eco-system awaiting new adventurous players to collect Kryxit! In our world, prepare yourself to earn crypto-currency and unique rare NFT while having a fun and cooperative experience with your friends. You can build your own character, fight in dungeons against bosses, stake your currency in the bank, loot from farming special items, cast spells contained from magical gems named Kryxit that can be linked to your items for accessibility.' FROM games WHERE igdb_id = 194842 ON CONFLICT (game_id, language_code) DO NOTHING;
