INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mist', 'Collect NFTs, battle epic monsters, and explore infinite immersive environments in this blockchain-based NFT Action RPG built on the Mist NFT Framework. The game universe connects to the MIST native token as the in-game currency, allowing you to farm and stake tokens to earn in- and out- of game rewards.' FROM games WHERE igdb_id = 200629 ON CONFLICT (game_id, language_code) DO NOTHING;
