INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Video Game Fables', '"Video Game Fables" is a fun, lighthearted RPG adventure set in a once-traditional RPG world that hasn''t had a player in decades. The world''s script gets completely ruined by someone calling herself "The Forsaken Princess." It''s up to Aru (the world''s princess), Nate (an NPC aspiring to be a hero), and Tator (the villain''s son) to get things back to normal...or maybe change everything forever.' FROM games WHERE igdb_id = 156920 ON CONFLICT (game_id, language_code) DO NOTHING;
