INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('five-nights-at-fuzzboobs-definitive-edition', 240483, '2022-09-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8sb6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3hbm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Five Nights at FuzzBoob''s: Definitive Edition', 'Congratulations! You''re Hired as a Night Guard! We are delighted to inform you that you have been selected for the position of Summer Night Guard (00:00 - 06:00) has been successful! Your responsibilities will include maintaining the security of our premises from 00:00 to 06:00, ensuring the safety of our property during the night shift. At Freddy FuzzBoob''s Pizza Party Pussy Palace, we strive to ensure adults can have some delicious pizza, drinks, and pleasure. Our main attraction is Freddy FuzzBoob and her two partners: Bonnie FuzzBoob and Chica FuzzBoob. They are animatronic fursluts, programmed to drain balls and ruin your innocence along the way. If you have any questions or require further information, please feel free to reach out. Once again, congratulations on your successful application, and welcome to the FuzzBoob''s family. We look forward to having you on board!' FROM games WHERE igdb_id = 240483 ON CONFLICT (game_id, language_code) DO NOTHING;
