INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Time', 'Big Time is a multiplayer action RPG that takes players through time and space to encounter some of history''s most famous - and infamous - figures. The mission is to reveal a mysterious threat that''s tearing down the walls of time and collapsing history in completely unexpected ways. All of this can be experienced through an expansive online game that enables hundreds of players to hack-''n''-slash their way through Big Time''s Open World together. Players can form parties, explore Adventure Instances, and defeat enemies for a chance at epic loot.' FROM games WHERE igdb_id = 194907 ON CONFLICT (game_id, language_code) DO NOTHING;
