INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rogue-legacy-2', 132058, '2022-04-28', 91, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4p51.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/argeh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rogue Legacy 2', 'Rogue Legacy is back! But now it''s got a 2 on the end of it! Rogue Legacy 2 is a genealogical rogue-lite. That means it has all the trappings of a typical rogue-like (randomized runs, changing characters, and more), but with persistent upgrades, and persistent dead heirs. In this game, your legacy defines you. Spend your parents’ inheritance and grow the family manor to give your children a better fighting chance. Each child is unique, with their own traits and abilities. Your daughter could be a Ranger. She could also be vegan. It’s a new experience every time. Rogue Legacy 2 also lets you play how you want to. Go hard and fast, and dive deeper into the depths of a randomly-generated world. Or take it slow and steady and build your character up until you’re ready for greater challenges.' FROM games WHERE igdb_id = 132058 ON CONFLICT (game_id, language_code) DO NOTHING;
